import{CustomElement}from"chrome://resources/js/custom_element.js";import{getTemplate}from"./dlp_clipboard_tab.html.js";import{EndpointType,PageHandler}from"./dlp_internals.mojom-webui.js";const EndpointTypeMap={[EndpointType.kDefault]:"Default",[EndpointType.kUrl]:"URL",[EndpointType.kClipboardHistory]:"Clipboard History",[EndpointType.kUnknownVm]:"Unknown VM",[EndpointType.kArc]:"Arc",[EndpointType.kBorealis]:"Borealis",[EndpointType.kCrostini]:"Crostini",[EndpointType.kPluginVm]:"Plugin VM",[EndpointType.kLacros]:"Lacros"};export class DlpClipboardElement extends CustomElement{static get is(){return"dlp-clipboard-tab"}static get template(){return getTemplate()}set clipboardSourceTypeString(clipboardSourceTypeString){this.setValueToElement("#clipboard-source-type",clipboardSourceTypeString)}set clipboardSourceUrlString(clipboardSourceUrlString){this.setValueToElement("#clipboard-source-url",clipboardSourceUrlString)}constructor(){super();this.pageHandler=PageHandler.getRemote()}connectedCallback(){this.fetchClipboardSourceInfo()}setClipboardInfo(source){if(!source){this.clipboardSourceTypeString="undefined";this.clipboardSourceUrlString="undefined";return}this.clipboardSourceTypeString=`${this.endpointTypeToString(source.type)}`;if(source.url===undefined){this.clipboardSourceUrlString="undefined"}else{this.clipboardSourceUrlString=source.url}}async fetchClipboardSourceInfo(){this.pageHandler.getClipboardDataSource().then((value=>{this.setClipboardInfo(value.source)})).catch((e=>{console.warn(`getClipboardDataSource failed: ${JSON.stringify(e)}`)}))}setValueToElement(elementId,stringValue){const htmlElement=this.$(elementId);if(htmlElement){htmlElement.innerText=stringValue}else{console.error(`Could not find ${elementId} element.`)}}endpointTypeToString(type){return EndpointTypeMap[type]||"invalid"}}customElements.define(DlpClipboardElement.is,DlpClipboardElement);